#!/usr/bin/env bash
#
# Selective test execution on CI, on top of Mill's `selective.prepare` / `selective.run`.
#
# Mill snapshots the inputs of the requested tasks (sources, `Task.Input` values, and the code
# signature of the build methods) at the base commit of a pull request, and only runs the tests
# that transitively depend on something that changed since then. Tests that don't exist at the
# base commit count as changed.
#
# Usage:
#   selective-tests.sh prepare <selector>...    (empty selectors are ignored)
#   selective-tests.sh run [Mill option]... <selector> [-- <task argument>...]
#   selective-tests.sh affected <selector>
#
# Selectors are Mill task selectors of test tasks, like `__:CsScalaJsTests.testForked` (see the
# `*CiTests` traits in mill-build). They must list the test tasks themselves: a command
# depending on several test tasks would be re-run, along with all of these tests, as soon as a
# single one of them is affected by a change.
#
# `prepare` must run once per job, before any `run`. It checks out the base commit of the pull
# request, snapshots the inputs of the tests of all the selectors, and checks out the pull request
# again. When selective execution can't be used - the build isn't a pull request build, the pull
# request changes the Mill version, a file Mill doesn't track but that drives how the tests of the
# job run (see below), or the selectors can't be resolved at the base commit - `run` runs all the
# tests of its selector.
#
# Mill tracks the files the build reads through `Task.Source(s)` (sources, test resources, the
# test-metadata submodules, …) and the build code, but not the CI configuration or the scripts it
# runs. So `prepare` falls back to running everything when one of these changed:
# - the definition of the current job (`GITHUB_JOB`) in the workflow file, the jobs it
#   transitively `needs`, or the workflow-level settings (everything before `jobs:`), comments
#   and blank lines aside - changes to the other jobs, like the release-only ones, don't matter
#   (the whole workflow file is compared when `GITHUB_JOB` isn't set),
# - the paths of `always_relevant_paths` below, that matter to every job,
# - the paths listed in `SELECTIVE_TESTS_EXTRA_PATHS`, that the job running `prepare` sets to
#   the other files it uses, like the scripts its steps run.
# This is an allowlist: changes to other files of `.github`, like release-only scripts, don't
# disable selective execution. So a job that starts using a new script or file Mill doesn't
# track must add it to its `SELECTIVE_TESTS_EXTRA_PATHS` (or to `always_relevant_paths` if
# every job uses it).
#
# Task arguments after `--` are passed to all the tasks of the selector that run, like
# `run '__.fix' -- --check`.
#
# `affected` doesn't run anything: it only tells whether the changes affect some task of its
# selector, as `affected=true` or `affected=false` in `$GITHUB_OUTPUT`, so that a job can skip
# steps that don't go through Mill's selective execution, like building and testing the native
# launchers. Like `run`, it must follow a `prepare`, and it considers everything affected when
# selective execution can't be used.
#
# Environment:
#   SELECTIVE_TESTS_BASE_SHA     base commit of the pull request (empty or unset otherwise)
#   SELECTIVE_TESTS_EXTRA_PATHS  whitespace-separated paths, relative to the repository root,
#                                whose changes disable selective execution in this job, on top of
#                                `always_relevant_paths`
#   GITHUB_EVENT_NAME            set by GitHub Actions, selective execution is used for pull_request only
#   GITHUB_JOB                   set by GitHub Actions, id of the current job in the workflow file
#   SCALA_VERSION, CI, …         read by build.mill, must be the same for `prepare` and `run`

set -euo pipefail

if [[ "$OSTYPE" == msys* || "$OSTYPE" == mingw* || "$OSTYPE" == cygwin* ]]; then
  MILL=./mill.bat
else
  MILL=./mill
fi

# Makes the build use a commit-independent version, so that the version baked into the sources
# generated by the build doesn't invalidate every test on every commit.
# See CoursierPublishModule.fixedVersionEnvVar in mill-build.
export COURSIER_SELECTIVE_TESTING=true

out_dir="${MILL_OUTPUT_DIR:-out}"
# written by selective.prepare, read by selective.run
snapshot="$out_dir/mill-selective-execution.json"
# our own copy of it, so that several `run`s can follow a single `prepare`
saved_snapshot="$out_dir/ci-selective-execution.json"

# Files Mill doesn't track that drive how the tests of every job run: the Mill launchers and this
# script. Jobs add their own files via SELECTIVE_TESTS_EXTRA_PATHS. The workflow file is checked
# separately, see workflow_relevant_part.
always_relevant_paths=(
  mill
  mill.bat
  .github/scripts/selective-tests.sh
)

workflow=.github/workflows/ci.yml

# Prints a part of the workflow file read from stdin, without comments and blank lines:
# - `workflow_part header`: the workflow-level settings, everything but the jobs,
# - `workflow_part job <id>`: the definition of job <id>, empty if there's no such job.
# Relies on the layout of ci.yml: top-level keys at column 0, job ids indented by 2 spaces.
workflow_part() {
  awk -v mode="$1" -v job="${2:-}" -v quotes="[\"']" '
    /^[[:space:]]*#/ || /^[[:space:]]*$/ { next }
    /^jobs:/ { in_jobs = 1; next }
    /^[^ ]/ { in_jobs = 0 }
    !in_jobs { if (mode == "header") print; next }
    /^  [^ ]/ {
      current = $0
      sub(/^  /, "", current)
      sub(/:.*/, "", current)
      gsub(quotes, "", current)
    }
    mode == "job" && current == job { print }
  '
}

# Prints the ids of the jobs that the job definition read from stdin `needs`, one per line.
# Handles `needs: a`, `needs: [a, b]`, and `needs:` followed by a `- a` list.
job_needs() {
  awk -v quotes="[\"']" '
    { sub(/[[:space:]]+#.*/, "") }
    /^    needs:/ {
      value = $0
      sub(/^    needs:[[:space:]]*/, "", value)
      if (value == "") {
        in_list = 1
      } else {
        gsub(/\[/, " ", value)
        gsub(/\]/, " ", value)
        gsub(/,/, " ", value)
        gsub(quotes, "", value)
        print value
      }
      next
    }
    in_list && /^ +- / {
      value = $0
      sub(/^ +- */, "", value)
      gsub(quotes, "", value)
      print value
      next
    }
    { in_list = 0 }
  '
}

# Prints the parts of the workflow file content $1 that matter to job $2: the workflow-level
# settings, the definition of the job, and those of the jobs it transitively needs (whose outputs
# it can read).
workflow_relevant_part() {
  local content="$1" pending="$2" seen=" " job block need
  workflow_part header <<< "$content"
  while [ -n "$pending" ]; do
    job="${pending%% *}"
    pending="${pending#"$job"}"
    pending="${pending# }"
    case "$seen" in
      *" $job "*) continue ;;
    esac
    seen="$seen$job "
    block="$(workflow_part job "$job" <<< "$content")"
    echo "# job $job"
    if [ -z "$block" ]; then
      echo "# no such job"
      continue
    fi
    echo "$block"
    for need in $(job_needs <<< "$block"); do
      pending="$pending $need"
    done
    pending="${pending# }"
  done
}

# Tells whether the parts of the workflow file that matter to the current job changed between
# commit $1 and the working tree (and prints how when they did)
workflow_changed() {
  local base="$1"
  local job="${GITHUB_JOB:-}"
  if [ -z "$job" ]; then
    if git diff --quiet "$base" -- "$workflow"; then
      return 1
    fi
    echo "$workflow changed since the base commit"
    return 0
  fi
  local base_content head_content base_part head_part
  if ! base_content="$(git show "$base:$workflow")"; then
    return 0
  fi
  head_content="$(cat "$workflow")"
  base_part="$(workflow_relevant_part "$base_content" "$job")"
  head_part="$(workflow_relevant_part "$head_content" "$job")"
  if [ "$base_part" = "$head_part" ]; then
    return 1
  fi
  echo "The definition of job $job in $workflow, of the jobs it needs, or the workflow settings changed:"
  diff <(echo "$base_part") <(echo "$head_part") || true
  return 0
}

# Joins selectors into a single `{a,b,c}` one: the `selective.*` commands only take
# their first positional argument into account, extra ones are silently dropped.
# Empty selectors are ignored, and a single selector is left as is (`{a}` isn't expanded).
brace_selector() {
  local selectors=()
  local selector
  for selector in "$@"; do
    if [ -n "$selector" ]; then
      selectors+=("$selector")
    fi
  done
  if [ "${#selectors[@]}" -eq 0 ]; then
    echo ""
  elif [ "${#selectors[@]}" -eq 1 ]; then
    echo "${selectors[0]}"
  else
    local IFS=","
    echo "{${selectors[*]}}"
  fi
}

prepare() {
  rm -f "$saved_snapshot"

  local selector
  selector="$(brace_selector "$@")"
  if [ -z "$selector" ]; then
    echo "No tests to snapshot"
    return
  fi

  local base="${SELECTIVE_TESTS_BASE_SHA:-}"
  if [ "${GITHUB_EVENT_NAME:-}" != "pull_request" ] || [ -z "$base" ]; then
    echo "Not a pull request build, all tests will run"
    return
  fi

  local head
  head="$(git rev-parse HEAD)"

  # no `| head -n 1`: under `pipefail`, `git show` would be killed by SIGPIPE once head exits
  local base_build_mill head_build_mill base_mill_version head_mill_version
  base_build_mill="$(git show "$base:build.mill")"
  head_build_mill="$(cat build.mill)"
  base_mill_version="${base_build_mill%%$'\n'*}"
  head_mill_version="${head_build_mill%%$'\n'*}"
  if [ "$base_mill_version" != "$head_mill_version" ]; then
    echo "Mill version differs between the base commit and the pull request, all tests will run"
    return
  fi

  # Mill doesn't track these, while they drive how tests run - and the native launchers are built
  local extra_paths=()
  read -r -a extra_paths <<< "${SELECTIVE_TESTS_EXTRA_PATHS:-}"
  local changed_paths
  if ! changed_paths="$(git diff --name-only "$base" "$head" -- \
    "${always_relevant_paths[@]}" ${extra_paths[@]+"${extra_paths[@]}"})"; then
    echo "Could not diff base commit $base with the pull request, all tests will run"
    return
  fi
  if [ -n "$changed_paths" ]; then
    echo "Files that Mill doesn't track changed since the base commit, all tests will run:"
    echo "$changed_paths"
    return
  fi
  if workflow_changed "$base"; then
    echo "All tests will run"
    return
  fi

  echo "Snapshotting the inputs of the tests at base commit $base"
  if ! git checkout --quiet "$base"; then
    echo "Could not check out base commit $base, all tests will run"
    return
  fi
  git submodule update --init --quiet

  local ok=true
  # fails if a selector can't be resolved at the base commit, like when it relies on a trait
  # the pull request adds
  if ! "$MILL" -i selective.prepare "$selector"; then
    ok=false
  fi

  git checkout --quiet "$head"
  git submodule update --init --quiet

  if $ok && [ -f "$snapshot" ]; then
    cp "$snapshot" "$saved_snapshot"
    echo "Selective execution enabled: only the tests affected by changes since $base will run"
  else
    echo "Could not snapshot the inputs of the tests at base commit $base, all tests will run"
  fi
}

run() {
  local args=() task_args=()
  while [ "$#" -gt 0 ]; do
    if [ "$1" = "--" ]; then
      shift
      task_args=("$@")
      break
    fi
    args+=("$1")
    shift
  done
  if [ "${#args[@]}" -eq 0 ]; then
    echo "Usage: $0 run [Mill option]... <selector> [-- <task argument>...]" >&2
    exit 1
  fi
  local selector="${args[${#args[@]}-1]}"
  local mill_opts=("${args[@]:0:${#args[@]}-1}")
  # `${a[@]+"${a[@]}"}`: with `set -u`, bash < 4.4 (macOS) rejects "${a[@]}" for an empty array

  if [ ! -f "$saved_snapshot" ]; then
    echo "Running all tests"
    "$MILL" -i ${mill_opts[@]+"${mill_opts[@]}"} "$selector" ${task_args[@]+"${task_args[@]}"}
    return
  fi

  cp "$saved_snapshot" "$snapshot"
  echo "Inputs that changed since the base commit:"
  "$MILL" -i --ticker false selective.resolveChanged "$selector" || true
  echo "Tests affected by those changes:"
  "$MILL" -i --ticker false selective.resolve "$selector"
  # selective.run passes the arguments following the selector to the tasks it runs
  "$MILL" -i ${mill_opts[@]+"${mill_opts[@]}"} selective.run "$selector" ${task_args[@]+"${task_args[@]}"}
}

affected() {
  if [ "$#" -ne 1 ]; then
    echo "Usage: $0 affected <selector>" >&2
    exit 1
  fi
  local selector="$1"
  local result=true

  if [ -f "$saved_snapshot" ]; then
    cp "$saved_snapshot" "$snapshot"
    echo "Inputs that changed since the base commit:"
    "$MILL" -i --ticker false selective.resolveChanged "$selector" || true
    local tasks
    tasks="$("$MILL" -i --ticker false selective.resolve "$selector")"
    if [ -z "$(echo "$tasks" | tr -d '[:space:]')" ]; then
      echo "No task affected by those changes"
      result=false
    else
      echo "Tasks affected by those changes:"
      echo "$tasks"
    fi
  else
    echo "Considering all tasks affected"
  fi

  if [ -n "${GITHUB_OUTPUT:-}" ]; then
    echo "affected=$result" >> "$GITHUB_OUTPUT"
  fi
}

case "${1:-}" in
  prepare)
    shift
    if [ "$#" -eq 0 ]; then
      echo "Usage: $0 prepare <selector>..." >&2
      exit 1
    fi
    prepare "$@"
    ;;
  run)
    shift
    run "$@"
    ;;
  affected)
    shift
    affected "$@"
    ;;
  *)
    echo "Usage: $0 prepare <selector>... | run [Mill option]... <selector> [-- <task argument>...] | affected <selector>" >&2
    exit 1
    ;;
esac
